@sig trait ShipProgressQualification_Api {
  def id: Art.BridgeId
  def shipSample_Id : Art.PortId
  def qualifiedShipProgress_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var qualifiedShipProgress: Mining_Cargo_Transfer_Supervisor.QualifiedShipProgress.Type = $

  def put_qualifiedShipProgress(value : Mining_Cargo_Transfer_Supervisor.QualifiedShipProgress.Type) : Unit = {
    Contract(
      Modifies(qualifiedShipProgress),
      Ensures(
        qualifiedShipProgress == value
      )
    )
    Spec {
      qualifiedShipProgress = value
    }

    Art.putValue(qualifiedShipProgress_Id, Mining_Cargo_Transfer_Supervisor.QualifiedShipProgress_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class ShipProgressQualification_Initialization_Api (
  val id: Art.BridgeId,
  val shipSample_Id : Art.PortId,
  val qualifiedShipProgress_Id : Art.PortId) extends ShipProgressQualification_Api

@datatype class ShipProgressQualification_Operational_Api (
  val id: Art.BridgeId,
  val shipSample_Id : Art.PortId,
  val qualifiedShipProgress_Id : Art.PortId) extends ShipProgressQualification_Api {

  // Logika spec var representing port state for incoming data port
  @spec var shipSample: Mining_Cargo_Transfer_Supervisor.ShipTransferSample = $

  def get_shipSample() : Option[Mining_Cargo_Transfer_Supervisor.ShipTransferSample] = {
    Contract(
      Ensures(
        Res == Some(shipSample)
      )
    )
    val value : Option[Mining_Cargo_Transfer_Supervisor.ShipTransferSample] = Art.getValue(shipSample_Id) match {
      case Some(Mining_Cargo_Transfer_Supervisor.ShipTransferSample_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port shipSample.  Expecting 'Mining_Cargo_Transfer_Supervisor.ShipTransferSample_Payload' but received ${v}")
        None[Mining_Cargo_Transfer_Supervisor.ShipTransferSample]()
      case _ => None[Mining_Cargo_Transfer_Supervisor.ShipTransferSample]()
    }
    return value
  }
}
